import{_ as i,l as n,o as t,c as l,v as e,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Barro 税收平滑","description":"","frontmatter":{"title":"Barro 税收平滑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tax-smoothing-barro.md","filePath":"econ/tax-smoothing-barro.md","lastUpdated":1789023840000}'),u={name:"econ/tax-smoothing-barro.md"};function B(c,a,m,E,_,P){const o=n("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="barro-税收平滑" tabindex="-1">Barro 税收平滑 <a class="header-anchor" href="#barro-税收平滑" aria-label="Permalink to &quot;Barro 税收平滑&quot;">​</a></h1><div class="epigraph"><p>扭曲税的边际成本应像永久收入那样平滑；暂时的支出用发债摊开，税率跟着永久支出走，而不是每年把预算轧平。</p><footer>—— Barro, On the Determination of the Public Debt, JPE 1979</footer></div><p><a href="/econ/fiscal-multiplier">上一课</a>在李嘉图与名义刚性下给出 \\(G\\) 与减税的乘数，并声明一次总付税债互换可以不改 \\(C\\)。本课的缺口是换税种：若税是扭曲的（劳动、消费税），时间路径本身有成本，最优不是每期平衡预算，而是平滑税率。Barro（1979）把公共债务写成税收平滑的缓冲。物价水平的财政理论下一课才问名义锚是否由盈余现值定；本课先在实际量上写债务。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乘数课的李嘉图用一次总付税：税的<strong>时机</strong>不扭曲，只有现值进财富。劳动税、销售税使边际决策变形，凸的超额负担意味着税率波动本身有成本——与消费的永久收入同构。缺口是：给定支出路径 \\(\\{G_t\\}\\)（含战争等暂时高峰），如何选 \\(\\{ \\tau_t\\}\\) 与债务。Barro：近似随机游走的税率，\\(\\tau_t\\approx\\mathbb{E}_t\\tau_{t+1}\\)，暂时 \\(G\\) 用赤字，永久 \\(G\\) 用永久更高的 \\(\\tau\\)。这与「每年平衡预算」或「金规则只为资本项目发债」都不同。</p><p><span class="marginnote">平滑的是税率（边际扭曲），不是税收收入。税基随 \\(Y\\) 变时，收入可以波动，税率仍平。自动稳定器下一课才把税基弹性当宏观缓冲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划者最小化扭曲的现值，约束是政府跨期预算（不含一次总付）。一阶条件使相邻期边际扭曲的贴现值对齐，故 \\(\\tau\\) 近随机游走。债务是状态：吸收 \\(G\\) 与税基的暂时冲击。预期到的永久战争：\\(\\tau\\) 立刻跳到新的永久水平，以免未来再跳。这与家庭 PIH 同构，对象是税。Ramsey 商品税（Ramsey 课）给出税种结构；本课只谈<strong>同一税种的时间平滑</strong>。</p>',8)),(t(),s(h,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%94%AF%E5%87%BA%E8%B7%AF%E5%BE%84%20G%22%5D%20--%3E%20SMOOTH%5B%22%E7%A8%8E%E7%8E%87%E5%B9%B3%E6%BB%91%22%5D%0A%20%20SMOOTH%20--%3E%20TAU%5B%22%CF%84%20%E2%89%88%20E%CF%84%E2%80%B2%22%5D%0A%20%20TEMP%5B%22%E6%9A%82%E6%97%B6%20G%22%5D%20--%3E%20DEBT%5B%22%E5%80%BA%E5%8A%A1%E7%BC%93%E5%86%B2%22%5D%0A%20%20PERM%5B%22%E6%B0%B8%E4%B9%85%20G%22%5D%20--%3E%20JUMP%5B%22%CF%84%20%E7%AB%8B%E5%88%BB%E4%B8%8A%E7%A7%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>李嘉图在扭曲税下部分破裂：税的时机改变劳动供给与消费的跨期价格，乘数与平滑同时存在。下限上若要用 \\(G\\) 刺激，平滑仍要求事后用债务摊还，而不是立刻用扭曲税轧平把刺激抵消掉——与乘数课的规则依赖一致。</p><h3 id="不是为发债而发债" tabindex="-1">不是为发债而发债 <a class="header-anchor" href="#不是为发债而发债" aria-label="Permalink to &quot;不是为发债而发债&quot;">​</a></h3><p>平滑给出债务的<strong>规范</strong>用途：保险税基与摊平暂时支出。它不给债务水平一个与 \\(\\pi\\) 无关的上限故事，也不等于 FTPL。不可持续的债务路径会在下一课变成价格水平跳跃或违约。本课假设政府仍满足现值约束。</p><h3 id="平滑不是周期乘数菜单" tabindex="-1">平滑不是周期乘数菜单 <a class="header-anchor" href="#平滑不是周期乘数菜单" aria-label="Permalink to &quot;平滑不是周期乘数菜单&quot;">​</a></h3><p>暂时 \\(G\\) 用债，是为了不让 \\(\\tau\\) 的平方超额负担集中爆发。它不回答 \\(G\\) 本身该不该在下限上加大——那是乘数课的规则依赖。</p><p>两句话要一起读：刺激可以暂时抬 \\(G\\)，融资应平滑 \\(\\tau\\)，而不是当年加扭曲税把刺激对冲掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>战争或灾难使 \\(G\\) 暂时升高：若立刻用高 \\(\\tau\\) 融资，超额负担以税率的平方上升。发债把 \\(\\tau\\) 的升幅摊到未来多期，每期扭曲更小，现值更低。和平后盈余还债，\\(\\tau\\) 不必低于平滑路径去「还清」得过快。资本税的时间不一致（承诺课）会破坏这条平滑：将来的自己想抽资本存量的一次性税。Barro 的随机游走默认承诺能维持。</p><p>乘数课的一次总付减税不改变扭曲路径；本课的减税若降低 \\(\\tau\\)，必须用未来 \\(\\tau\\) 或支出补上现值，否则不是平滑而是改永久税率。把刺激性减税写成税收平滑，会把周期政策与 Ramsey 时间路径焊成一句。平滑允许周期中税基波动造成的赤字，不允许把永久支出当成暂时来发债。</p><p>开放经济下，债务可以卖给外国人，\\(S-I\\) 与 FH 相关再进来；平滑仍是税率逻辑。CIP 不决定 \\(\\tau\\) 路径，实证见 <code>/quant/irp</code>。</p><p><span class="marginnote">通胀税是另一种扭曲税。未预期通胀可以降低实际债，像一次性资本税，破坏平滑与承诺。本课的 \\(\\tau\\) 先指明文税率。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优债务/GDP，不把平滑写成「可以无限赤字」。FTPL 下一课：若盈余现值钉不住， \\(P\\) 会跳。自动稳定器把 \\(\\tau\\) 规则写成周期函数，与平滑的「税率不随暂时 \\(Y\\) 动」在字面上紧张——稳定器平滑的是私人收入，税率表可以累进；Barro 平滑的是边际税率的随机游走。声明对象，不要焊死。</p><p>战争之外，衰退中的暂时 \\(G\\) 或暂时低税基，平滑同样指向赤字，而不是立刻加税把乘数课的刺激抵消。永久的老龄化支出必须进永久 \\(\\tau\\)，不能靠滚动债务假装暂时。这是会计上的永久/暂时分解，不是政治上的「以后再调」。李嘉图一次总付下时机无成本；本课一旦引入扭曲，时机就是福利对象。</p><p>后课默认：扭曲税下债务是平滑缓冲，税率近随机游走；一次总付李嘉图不再是唯一基准。下一课：名义债务与物价水平是否由财政现值决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乘数课用一次总付；本课用扭曲税的时间路径。</li><li>Barro：\\(\\tau\\) 近随机游走，暂时 \\(G\\) 用债，永久 \\(G\\) 用永久 \\(\\tau\\)。</li><li>平滑的是边际扭曲，不是每期预算平衡。</li><li>现值约束仍要满足；FTPL 是下一课的名义接头。</li><li>出处：Barro, <em>JPE</em> 1979。</li></ul>',17))])}const A=i(u,[["render",B]]);export{f as __pageData,A as default};
